import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { createSocialConnectHandler } from "/workspace/scratch/ccfbf7e5800b/purama-ai/supabase/functions/_shared/social-connection-core.ts";

const source = "/workspace/scratch/ccfbf7e5800b/purama-ai/supabase/functions/_shared/social-connection-core.ts";
const cases: Record<string, unknown>[] = [];

async function probe(kind: "oversized-open" | "aborted-open" | "oversized-closed") {
  let dependencyCalls = 0;
  let streamController!: ReadableStreamDefaultController<Uint8Array>;
  const parent = new AbortController();
  const body = new ReadableStream<Uint8Array>({
    start(controller) {
      streamController = controller;
      controller.enqueue(new TextEncoder().encode(kind === "aborted-open" ? '{"platform":"youtube"}' : "x".repeat(5000)));
      if (kind === "oversized-closed") controller.close();
    },
  });
  const handler = createSocialConnectHandler({
    appUrl: "https://app.example", callbackBaseUrl: "https://database.example/functions/v1/social-callback",
    stateSecret: "fixture-only-secret-at-least-thirty-two-characters",
    getUserId: async () => "11111111-1111-4111-8111-111111111111",
    getDependencies: () => { dependencyCalls++; throw new Error("unexpected dependency creation"); },
  });
  const request = new Request("https://database.example/functions/v1/social-connect", {
    method: "POST", headers: { Origin: "https://app.example", "Content-Type": "application/json" },
    body, signal: parent.signal, duplex: "half",
  } as RequestInit);
  let timer: ReturnType<typeof setTimeout> | undefined;
  const started = performance.now();
  const pending = handler(request);
  if (kind === "aborted-open") parent.abort();
  const result = await Promise.race([
    pending.then(response => ({ outcome: "response", status: response.status })),
    new Promise<{ outcome: string; status: null }>(resolve => {
      timer = setTimeout(() => resolve({ outcome: "watchdog", status: null }), 150);
    }),
  ]);
  if (timer) clearTimeout(timer);
  const elapsedMs = performance.now() - started;
  if (kind !== "oversized-closed") streamController.error(new Error("synthetic cleanup"));
  await pending;
  assert.equal(dependencyCalls, 0);
  if (kind === "oversized-closed") assert.equal(result.status, 413);
  else assert.equal(result.outcome, "watchdog");
  cases.push({ kind, ...result, elapsedMs: Math.round(elapsedMs), signalAborted: request.signal.aborted, dependencyCalls });
}

for (const kind of ["oversized-open", "aborted-open", "oversized-closed"] as const) await probe(kind);
console.log(JSON.stringify({
  source, sha256: createHash("sha256").update(readFileSync(source)).digest("hex"),
  node: process.version, cases, providerCalls: 0, productFilesChanged: 0,
  conclusion: "The existing inbound handler waits for EOF even after 5000 bytes or an aborted request signal; the finite oversized control returns 413.",
}, null, 2));

