import { createRequire } from 'node:module';

const require = createRequire('/workspace/scratch/ccfbf7e5800b/purama-ai/karta/package.json');
const { createClient } = require('@supabase/supabase-js');
vi.mock('/workspace/scratch/ccfbf7e5800b/purama-ai/karta/src/db/supabase.js', () => ({
  supabase: { schema() { throw new Error('Unexpected production database call'); } },
}));
const { createSocialStatusTool } = await import('/workspace/scratch/ccfbf7e5800b/purama-ai/karta/src/tools/social-status.ts');
const USER = '11111111-1111-4111-8111-111111111111';
const OTHER = '22222222-2222-4222-8222-222222222222';
const FIRST = 'aaaaaaaa-aaaa-4aaa-8aaa-000000000001';
const SECOND = 'aaaaaaaa-aaaa-4aaa-8aaa-000000000002';
const ctx = { userId: USER, agentType: 'maitre-des-publicites' as const, mode: 'live' as const };
const ERROR = 'Lecture de l’état social indisponible.';
function row(id = FIRST, user = USER) {
  return { id, user_id: user, status: 'publish_unconfirmed', target_platforms: ['instagram'],
    scheduled_at: null, published_at: null, created_at: null, updated_at: null, zernio_post_id: 'fixture-receipt' };
}
function tool(fetch: typeof globalThis.fetch, timeoutMs = 80) {
  const database = createClient('https://audit-social.invalid', 'test-sdk-key-not-a-secret', {
    auth: { persistSession: false, autoRefreshToken: false, detectSessionInUrl: false },
    global: { fetch },
  });
  return createSocialStatusTool({ database, schema: () => 'public', timeoutMs });
}

describe('Independent real SDK boundary probes for social_status', () => {
  it('accepts the successful SDK fixture as a positive control', async () => {
    const fetch = vi.fn<typeof globalThis.fetch>(async () => new Response(JSON.stringify([row()]), {
      headers: { 'Content-Type': 'application/json' },
    }));
    const result = await tool(fetch, 500).execute({ resource: 'posts' }, ctx);
    expect(result).toMatchObject({ status: 'read', resource: 'posts', items: [{ postId: FIRST, status: 'publish_unconfirmed' }],
      page: { limit: 10, hasMore: false, nextAfterId: null } });
    expect(fetch).toHaveBeenCalledOnce();
  });

  it('bounds a fetch that ignores cancellation before returning headers', async () => {
    let signal: AbortSignal | undefined;
    const fetch = vi.fn<typeof globalThis.fetch>(async (_input, init) => {
      signal = init?.signal as AbortSignal;
      return await new Promise<Response>(() => {});
    });
    const started = performance.now();
    await expect(tool(fetch).execute({ resource: 'posts' }, ctx)).rejects.toThrow(ERROR);
    expect(performance.now() - started).toBeLessThan(1500);
    expect(fetch).toHaveBeenCalledOnce();
    expect(signal?.aborted).toBe(true);
  });

  it('bounds a body that never finishes after valid headers and a JSON prefix', async () => {
    let signal: AbortSignal | undefined;
    let body!: ReadableStreamDefaultController<Uint8Array>;
    const stream = new ReadableStream<Uint8Array>({ start(c) { body = c; c.enqueue(new TextEncoder().encode('[')); } });
    const fetch = vi.fn<typeof globalThis.fetch>(async (_input, init) => {
      signal = init?.signal as AbortSignal;
      return new Response(stream, { status: 200, headers: { 'Content-Type': 'application/json' } });
    });
    try {
      await expect(tool(fetch).execute({ resource: 'posts' }, ctx)).rejects.toThrow(ERROR);
      expect(fetch).toHaveBeenCalledOnce();
      expect(signal?.aborted).toBe(true);
    } finally { body.error(new Error('Fixture cleanup')); }
  });

  it('cannot accept delayed headers after returning a timeout', async () => {
    let release!: (response: Response) => void;
    const fetch = vi.fn<typeof globalThis.fetch>(() => new Promise(resolve => { release = resolve; }));
    let accepted = 0;
    const outcome = tool(fetch).execute({ resource: 'posts' }, ctx)
      .then(() => { accepted++; return 'unexpected'; }, error => error.message);
    expect(await outcome).toBe(ERROR);
    release(new Response(JSON.stringify([row()]), { headers: { 'Content-Type': 'application/json' } }));
    await new Promise(resolve => setTimeout(resolve, 0));
    expect(accepted).toBe(0);
    expect(fetch).toHaveBeenCalledOnce();
  });

  it('rejects invalid UTF-8 inside a selected receipt after the real SDK decoder', async () => {
    const text = JSON.stringify([row()]);
    const prefix = text.slice(0, text.indexOf('fixture-receipt'));
    const suffix = text.slice(text.indexOf('fixture-receipt') + 'fixture-receipt'.length);
    const bytes = Buffer.concat([Buffer.from(prefix), Buffer.from([0xc3, 0x28]), Buffer.from(suffix)]);
    const fetch = vi.fn<typeof globalThis.fetch>(async () => new Response(bytes, {
      headers: { 'Content-Type': 'application/json' },
    }));
    await expect(tool(fetch, 500).execute({ resource: 'posts' }, ctx)).rejects.toThrow(ERROR);
    expect(fetch).toHaveBeenCalledOnce();
  });

  it('rejects a foreign sentinel received through the real SDK rather than publishing pagination evidence', async () => {
    const fetch = vi.fn<typeof globalThis.fetch>(async () => new Response(JSON.stringify([row(), row(SECOND, OTHER)]), {
      headers: { 'Content-Type': 'application/json' },
    }));
    await expect(tool(fetch, 500).execute({ resource: 'posts', limit: 1 }, ctx)).rejects.toThrow(ERROR);
    expect(fetch).toHaveBeenCalledOnce();
  });
});

